/* Animated dot grid - CSS-only replacement for JS animation */
@keyframes dot-pulse {
  0%, 100% { opacity: 0; transform: scale(0.5) rotate(45deg); }
  50% { opacity: 1; transform: scale(1) rotate(0deg); }
}

.dots .circle {
  animation: dot-pulse 4s ease-in-out infinite;
}

/* Staggered delays using prime-based pattern for pseudo-random feel */
.dot:nth-child(3n) .circle { animation-delay: 0.7s; animation-duration: 5s; }
.dot:nth-child(5n) .circle { animation-delay: 1.3s; animation-duration: 4.5s; }
.dot:nth-child(7n) .circle { animation-delay: 0.4s; animation-duration: 5.5s; }
.dot:nth-child(11n) .circle { animation-delay: 1.9s; animation-duration: 4s; }
